#!/usr/bin/env node
// Codemod: promote each package's `build` package.json script into a `run.tasks.build` vp task
// that excludes node_modules/.modules.yaml from the pack cache fingerprint. Idempotent: skips
// packages whose build script is already removed.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { execSync } from "node:child_process";
import path from "node:path";

const DRY = process.argv.includes("--dry");
const ROOTS = ["packages", "formats", "platforms", "renderers", "bundlers", "design", "ai", "plugins", "tools"];

// Find package.json files with a build script (exclude node_modules).
const pkgJsons = execSync(
  `grep -rl '"build"' --include=package.json ${ROOTS.join(" ")} 2>/dev/null | grep -v node_modules || true`,
  { encoding: "utf8", cwd: process.cwd() },
).split("\n").filter(Boolean);

const INPUT_LITERAL = `[{ auto: true }, { pattern: "!node_modules/.modules.yaml", base: "workspace" }]`;

function commandLiteral(build) {
  const parts = build.split("&&").map((s) => s.trim()).filter(Boolean);
  if (parts.length === 1) return JSON.stringify(parts[0]);
  return `[${parts.map((p) => JSON.stringify(p)).join(", ")}]`;
}

function buildTaskBlock(build, indent) {
  const cmd = commandLiteral(build);
  return [
    `${indent}build: {`,
    `${indent}  command: ${cmd},`,
    `${indent}  // node_modules/.modules.yaml is rewritten by every CI reinstall; excluding it keeps`,
    `${indent}  // vp pack a cache hit across jobs instead of re-packing on every run.`,
    `${indent}  input: ${INPUT_LITERAL},`,
    `${indent}},`,
  ].join("\n");
}

let changed = 0;
const skipped = [];

for (const pjPath of pkgJsons) {
  const pkg = JSON.parse(readFileSync(pjPath, "utf8"));
  const build = pkg.scripts?.build;
  if (!build) {
    skipped.push(`${pjPath} (no build script)`);
    continue;
  }
  const dir = path.dirname(pjPath);
  const vcPath = path.join(dir, "vite.config.ts");
  if (!existsSync(vcPath)) {
    skipped.push(`${pjPath} (no vite.config.ts)`);
    continue;
  }

  // 1) Remove build script from package.json.
  delete pkg.scripts.build;
  const pjOut = `${JSON.stringify(pkg, null, 2)}\n`;

  // 2) Insert/merge the build task into vite.config.ts.
  let vc = readFileSync(vcPath, "utf8");
  if (vc.includes("build: {")) {
    skipped.push(`${vcPath} (already has build task)`);
    continue;
  }

  if (/\n\s*run:\s*\{/.test(vc)) {
    // Merge into an existing run.tasks: { ... } — insert after the `tasks: {` line.
    const m = vc.match(/(\n)(\s*)tasks:\s*\{\n/);
    if (!m) {
      skipped.push(`${vcPath} (has run: but no tasks: — needs manual handling)`);
      continue;
    }
    const taskIndent = `${m[2]}  `;
    vc = vc.replace(m[0], `${m[0]}${buildTaskBlock(build, taskIndent)}\n`);
  } else {
    // Insert a fresh run block right after `defineConfig({`.
    const m = vc.match(/defineConfig\(\{\n/);
    if (!m) {
      skipped.push(`${vcPath} (no defineConfig object literal — needs manual handling)`);
      continue;
    }
    const block = [
      `  run: {`,
      `    tasks: {`,
      buildTaskBlock(build, "      "),
      `    },`,
      `  },`,
      ``,
    ].join("\n");
    vc = vc.replace(m[0], `${m[0]}${block}`);
  }

  changed += 1;
  if (DRY) {
    console.log(`--- ${dir} (build: ${build})`);
  } else {
    writeFileSync(pjPath, pjOut);
    writeFileSync(vcPath, vc);
  }
}

console.log(`\n${DRY ? "[dry] would change" : "changed"}: ${changed} packages`);
if (skipped.length) console.log(`skipped:\n  ${skipped.join("\n  ")}`);

