32	const run = (command: string, args: string[]): void => {
33	  const result = spawnSync(command, args, {
34	    cwd: docsRoot,
35	    stdio: "inherit",
36	  });
37	
38	  if (result.status !== 0) {
39	    throw new Error(`${command} ${args.join(" ")} failed with exit code ${result.status ?? -1}`);
40	  }
41	};
42	
43	const walkFiles = (dir: string): string[] => {
44	  if (!existsSync(dir)) {
45	    return [];
46	  }
47	
48	  const files: string[] = [];
49	  for (const name of readdirSync(dir)) {
50	    const fullPath = join(dir, name);
51	    const stat = statSync(fullPath);
52	    if (stat.isDirectory()) {
53	      files.push(...walkFiles(fullPath));
54	    } else {
55	      files.push(fullPath);
56	    }
57	  }
58	  return files;
59	};
60	
61	type SidebarItem = {
62	  text?: string;
63	  link?: string;
64	  items?: SidebarItem[];
65	};
66	
67	const translateSidebar = (item: SidebarItem, translate: (text: string) => string): SidebarItem => {
68	  const translated: SidebarItem = { ...item };
69	
70	  if (translated.text) {
71	    translated.text = translate(translated.text);
72	  }
73	
74	  if (translated.items) {
75	    translated.items = translated.items.map((child) => translateSidebar(child, translate));
76	  }
77	
78	  return translated;
79	};
80	
81	/** Collect every `text` label in a sidebar tree (for one batched translation pass). */
82	const collectSidebarText = (items: SidebarItem[], out: string[]): void => {
83	  for (const item of items) {
84	    if (item.text) out.push(item.text);
85	    if (item.items) collectSidebarText(item.items, out);
86	  }
87	};
88	
89	// Translated prose occasionally emits literal HTML tags (for example <dialog>), which Vue markdown
90	// parsing treats as real elements and can fail on missing end tags. Escape bare tag tokens in prose
91	// segments while leaving preserved HTML blocks/code fences untouched.
92	const escapeBareHtmlTags = (text: string): string =>
93	  text.replace(/<\/?([A-Za-z][\w-]*)>/g, (match) => {
94	    if (match.startsWith("</")) {
95	      const name = match.slice(2, -1);
96	      return `&lt;/${name}&gt;`;
97	    }
98	
99	    const name = match.slice(1, -1);
100	    return `&lt;${name}&gt;`;
101	  });
102	
103	const build = async (): Promise<void> => {
104	  const adapter = createTranslationAdapter();
105	  const memory = TranslationMemory.load("hu", "api");
106	
107	  rmSync(enApiDir, { recursive: true, force: true });
108	  rmSync(huApiDir, { recursive: true, force: true });
109	
110	  console.log("Generating EN API docs...");
111	  run("vp", ["exec", "typedoc", "--options", "typedoc.json", "--out", "api"]);
112	  run("node", ["scripts/style-api-badges.ts"]);
113	  run("node", ["scripts/write-api-overview.ts"]);
114	
115	  // The CSS API pages live under docs/api/css/; generate them after TypeDoc (which cleans docs/api) and
116	  // before the locale clone, so they're cloned + translated for HU for free.
117	  console.log("Generating CSS API docs...");
118	  run("node", ["scripts/build-css-api.ts"]);
119	
120	  console.log("Cloning API docs for HU locale...");
121	  mkdirSync(dirname(huApiDir), { recursive: true });
122	  cpSync(enApiDir, huApiDir, { recursive: true });
123	
124	  const files = walkFiles(huApiDir);
125	  const markdownFiles = files.filter((f) => f.endsWith(".md"));
126	  // The TypeDoc sidebar carries the CSS section too (merged by @cssdoc/typedoc), so its labels cover
127	  // both the TS API and the CSS reference.
128	  const sidebarFiles = files.filter((f) => f.endsWith("typedoc-sidebar.json"));
129	
130	  // 1. Markdown: segment each file into prose / deterministic-glossary / verbatim blocks. Prose is
131	  //    batched + cached through the selected adapter; headings, badge pills, and table column labels
132	  //    always go through the glossary (deterministic, keyless, never cached); everything else is kept
133	  //    verbatim. Block-level keys survive the scaffolding churn that busted whole-file keys.
134	  const glossary = new GlossaryTranslationAdapter();
135	  const segmented = markdownFiles.map((filePath) => ({
136	    filePath,
137	    segments: segmentMarkdown(readFileSync(filePath, "utf8")),
138	  }));
139	  const units = segmented.flatMap(({ segments }) => collectUnits(segments));
140	
141	  const glossaryText = new Map<string, string>();
142	  for (const unit of units) {
143	    if (unit.kind === "glossary" && !glossaryText.has(unit.text)) {
144	      // The glossary is synchronous under the hood; awaiting is just contract plumbing (instant).
145	      glossaryText.set(unit.text, await glossary.translateText(unit.text));
146	    }
147	  }
148	  const proseUnits: TranslationUnit[] = units
149	    .filter((unit) => unit.kind === "prose")
150	    .map((unit) => ({ kind: "prose", source: unit.text }));
151	  const proseTranslations = await translateUnits(adapter, memory, proseUnits, { autosave: true });
152	
153	  const resolve: Resolve = (text, kind) => {
154	    if (kind === "glossary") {
155	      return glossaryText.get(text) ?? text;
156	    }
157	
158	    const translated = proseTranslations.get(keyFor("prose", text)) ?? text;
159	    return escapeBareHtmlTags(translated);
160	  };
161	  for (const { filePath, segments } of segmented) {
162	    writeFileSync(filePath, reassemble(segments, resolve));
163	  }
164	
165	  // 2. Sidebars: collect every label across all trees, translate the misses in one batched pass,
166	  //    then rebuild each tree from the results.
167	  const sidebars = sidebarFiles.map((filePath) => ({
168	    filePath,
169	    tree: JSON.parse(readFileSync(filePath, "utf8")) as SidebarItem[],
170	  }));
171	  const labels: string[] = [];
172	  for (const { tree } of sidebars) collectSidebarText(tree, labels);
173	  const labelTranslations = await translateUnits(
174	    adapter,
175	    memory,
176	    labels.map((source) => ({ kind: "text", source })),
177	  );
178	  const translateLabel = (text: string): string =>
179	    labelTranslations.get(keyFor("text", text)) ?? text;
180	  for (const { filePath, tree } of sidebars) {
181	    const translated = tree.map((item) => translateSidebar(item, translateLabel));
182	    writeFileSync(filePath, `${JSON.stringify(translated, null, 2)}\n`);
183	  }
184	
185	  memory.save();
186	  const proseBlocks = new Set(proseUnits.map((u) => u.source)).size;
187	  console.log(
188	    `Localized ${markdownFiles.length} API markdown files for HU via '${adapter.name}': ` +
189	      `${glossaryText.size} glossary terms, ${proseBlocks} prose blocks, ${labels.length} sidebar labels ` +
190	      `(${memory.misses} translated, ${memory.hits} cached) in ${relative(docsRoot, huApiDir)}`,
191	  );
192	};
193	
194	build().catch((error: unknown) => {
195	  console.error(error);
196	  process.exitCode = 1;
197	});
