1	/**
2	 * Split generated API markdown into translatable segments.
3	 *
4	 * The locale pipeline used to hash and translate whole `.md` files. Generated docs churn on every
5	 * build (stability-badge flips, resolved token values, signature edits), so a whole-file key thrashed
6	 * and the page's prose reverted to English. This module cuts the file into blocks so only real prose
7	 * carries a content key — the scaffolding around it can change without busting the cache.
8	 *
9	 * Each segment is one of:
10	 * - `preserve` — emitted verbatim (code fences, signatures, breadcrumbs, type/link-only lines, HTML).
11	 * - `glossary` — deterministic term substitution (section headings, stability-badge pills, table
12	 *   column labels). Cheap, keyless, never cached.
13	 * - `prose`    — real translation (descriptions, remarks, `@example` captions, table Description cells).
14	 * - `table`    — a GFM table parsed into a grid so header labels + Description cells translate while
15	 *   code columns and structure stay verbatim. Only emitted when the grid rebuilds byte-for-byte to the
16	 *   source (see the round-trip self-check); otherwise the table falls back to `preserve`.
17	 *
18	 * `reassemble(segmentMarkdown(md), (t) => t)` is the identity — the split is lossless.
19	 *
20	 * @module
21	 */
22	
23	export type TranslationKind = "glossary" | "prose";
24	
25	export type Segment =
26	  | { kind: "preserve"; text: string }
27	  | { kind: "glossary"; text: string }
28	  | { kind: "prose"; text: string }
29	  | {
30	      kind: "table";
31	      rows: string[][];
32	      headerRow: number;
33	      separatorRow: number;
34	      /** Column indices whose body cells hold prose (a `Description`/`Summary` column). */
35	      descCols: number[];
36	    };
37	
38	/** A translatable unit: source text plus how it should be translated. */
39	export interface TranslatableUnit {
40	  text: string;
41	  kind: TranslationKind;
42	}
43	
44	/** How to resolve a translatable unit to its target text. Identity round-trips the source. */
45	export type Resolve = (text: string, kind: TranslationKind) => string;
46	
47	/** Strip inline code, markdown links, and HTML tags, then keep only Latin letters. */
48	const stripNonProse = (input: string): string =>
49	  input
50	    .replace(/`[^`]*`/g, " ")
51	    .replace(/\[[^\]]*\]\([^)]*\)/g, " ")
52	    .replace(/<[^>]+>/g, " ")
53	    .replace(/[^A-Za-z]+/g, " ")
54	    .trim();
55	
56	const hasProseWords = (input: string): boolean => stripNonProse(input).length > 0;
57	
58	/** A breadcrumb line: starts with a link and chains crumbs with ` / ` (the trailing crumb is plain). */
59	const isBreadcrumb = (line: string): boolean =>
60	  /^\[[^\]]+\]\([^)]+\)/.test(line) && line.includes(" / ");
61	
62	/** An em-dash-only or blank table cell carries no prose. */
63	const isEmptyCell = (cell: string): boolean => cell === "" || cell === "—" || cell === "-";
64	
65	/** A body cell worth translating: has prose words and isn't an empty placeholder. */
66	const isTranslatableCell = (cell: string): boolean => !isEmptyCell(cell) && hasProseWords(cell);
67	
68	/** A cell carrying a stability-badge pill localizes deterministically, not through the prose engine. */
69	const cellKind = (cell: string): TranslationKind =>
70	  cell.includes("pantoken-doc-tag") ? "glossary" : "prose";
71	
72	const FENCE = /^\s*```/;
73	
74	/** Split a table row into trimmed cells, honoring `\|`-escaped pipes inside cells. */
75	const parseRow = (line: string): string[] => {
76	  let inner = line.trim();
77	  if (inner.startsWith("|")) inner = inner.slice(1);
78	  if (inner.endsWith("|")) inner = inner.slice(0, -1);
79	  return inner.split(/(?<!\\)\|/).map((cell) => cell.trim());
80	};
81	
82	const rebuildRow = (cells: string[]): string => `| ${cells.join(" | ")} |`;
83	
84	/** A GFM separator row: every cell is `---`, `:--`, `--:`, or `:-:`. */
85	const isSeparatorRow = (line: string): boolean => {
86	  const cells = parseRow(line);
87	  return cells.length > 0 && cells.every((cell) => /^:?-+:?$/.test(cell));
88	};
89	
90	/** Classify a run of consecutive non-blank, non-fenced lines. */
91	const classifyBlock = (lines: string[]): Segment => {
92	  const text = lines.join("\n");
93	  const first = lines[0];
94	
95	  // Table: header row + separator. Only translate cells when the grid rebuilds exactly to the source,
96	  // so anything with unexpected spacing/escaping is preserved whole rather than silently reformatted.
97	  if (lines.length >= 2 && first.trimStart().startsWith("|") && isSeparatorRow(lines[1])) {
98	    const rows = lines.map(parseRow);
99	    if (rows.map(rebuildRow).join("\n") === text) {
100	      const descCols = rows[0]
101	        .map((header, index) => (/^(description|summary)$/i.test(header) ? index : -1))
102	        .filter((index) => index >= 0);
103	      return { kind: "table", rows, headerRow: 0, separatorRow: 1, descCols };
104	    }
105	    return { kind: "preserve", text };
106	  }
107	
108	  // Headings and stability-badge pills → deterministic glossary. The glossary no-ops on identifiers
109	  // (`### options?`) and on words it doesn't know, so routing every heading here is safe.
110	  if (/^#{1,6}\s/.test(first)) return { kind: "glossary", text };
111	  if (first.trimStart().startsWith("<")) {
112	    return { kind: text.includes("pantoken-doc-tag") ? "glossary" : "preserve", text };
113	  }
114	
115	  // Signatures/blockquotes, breadcrumbs, and lines that are only links/code/type expressions.
116	  if (first.trimStart().startsWith(">")) return { kind: "preserve", text };
117	  if (isBreadcrumb(first)) return { kind: "preserve", text };
118	  if (!hasProseWords(text)) return { kind: "preserve", text };
119	
120	  return { kind: "prose", text };
121	};
122	
123	/** Split markdown into ordered, lossless segments. */
124	export function segmentMarkdown(md: string): Segment[] {
125	  const lines = md.split("\n");
126	  const segments: Segment[] = [];
127	  let index = 0;
128	
129	  // Optional YAML frontmatter (generated API pages don't emit it today, but be safe).
130	  if (lines[0] === "---") {
131	    let end = 1;
132	    while (end < lines.length && lines[end] !== "---") end += 1;
133	    if (end < lines.length) {
134	      segments.push({ kind: "preserve", text: lines.slice(0, end + 1).join("\n") });
135	      index = end + 1;
136	    }
137	  }
138	
139	  let block: string[] = [];
140	  const flush = (): void => {
141	    if (block.length > 0) {
142	      segments.push(classifyBlock(block));
143	      block = [];
144	    }
145	  };
146	
147	  while (index < lines.length) {
148	    const line = lines[index];
149	
150	    if (FENCE.test(line)) {
151	      flush();
152	      const start = index;
153	      index += 1;
154	      while (index < lines.length && !FENCE.test(lines[index])) index += 1;
155	      if (index < lines.length) index += 1; // include the closing fence
156	      segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
157	      continue;
158	    }
159	
160	    if (line.trim() === "") {
161	      flush();
162	      const start = index;
163	      while (index < lines.length && lines[index].trim() === "") index += 1;
164	      segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
165	      continue;
166	    }
167	
168	    block.push(line);
169	    index += 1;
170	  }
171	  flush();
172	
173	  return segments;
174	}
175	
176	/** Every translatable unit across the segments, in document order (callers dedupe by content). */
177	export function collectUnits(segments: readonly Segment[]): TranslatableUnit[] {
178	  const units: TranslatableUnit[] = [];
179	  for (const segment of segments) {
180	    if (segment.kind === "glossary" || segment.kind === "prose") {
181	      units.push({ text: segment.text, kind: segment.kind });
182	      continue;
183	    }
184	    if (segment.kind === "table") {
185	      for (const header of segment.rows[segment.headerRow]) {
186	        if (header !== "") units.push({ text: header, kind: "glossary" });
187	      }
188	      for (let row = 0; row < segment.rows.length; row += 1) {
189	        if (row === segment.headerRow || row === segment.separatorRow) continue;
190	        for (const col of segment.descCols) {
191	          const cell = segment.rows[row][col];
192	          if (cell !== undefined && isTranslatableCell(cell)) {
193	            units.push({ text: cell, kind: cellKind(cell) });
194	          }
195	        }
196	      }
197	    }
198	  }
199	  return units;
200	}
201	
202	/** Rebuild markdown from segments, resolving each translatable unit through `resolve`. */
203	export function reassemble(segments: readonly Segment[], resolve: Resolve): string {
204	  return segments.map((segment) => renderSegment(segment, resolve)).join("\n");
205	}
206	
207	const renderSegment = (segment: Segment, resolve: Resolve): string => {
208	  switch (segment.kind) {
209	    case "preserve":
210	      return segment.text;
211	    case "glossary":
212	    case "prose":
213	      return resolve(segment.text, segment.kind);
214	    case "table":
215	      return renderTable(segment, resolve);
216	  }
217	};
218	
219	const renderTable = (segment: Extract<Segment, { kind: "table" }>, resolve: Resolve): string =>
220	  segment.rows
221	    .map((cells, row) => {
222	      const rendered = cells.map((cell, col) => {
223	        if (row === segment.separatorRow) return cell;
224	        if (row === segment.headerRow) return cell === "" ? cell : resolve(cell, "glossary");
225	        if (segment.descCols.includes(col) && isTranslatableCell(cell)) {
226	          return resolve(cell, cellKind(cell));
227	        }
228	        return cell;
229	      });
230	      return rebuildRow(rendered);
231	    })
232	    .join("\n");
