1	/**
2	 * A content-addressed translation memory plus the batch driver both locale pipelines share.
3	 *
4	 * The pipelines used to re-translate every file on every run — one `claude -p` spawn per API
5	 * markdown file and per sidebar label. This module cuts that to the diff: each translatable unit is
6	 * keyed by a hash of its source text, so unchanged content is served from a committed cache and only
7	 * new or edited units reach the adapter. Small units (sidebar labels) are objectified into a single
8	 * batched request; large markdown is translated per file on a miss to keep fidelity.
9	 *
10	 * The flow is: diff (hash vs. cache) → objectify (batch the misses) → translate → destructure (map
11	 * results back by hash) → save (prune to the units seen this run, write JSON).
12	 *
13	 * @module
14	 */
15	import { createHash } from "node:crypto";
16	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
17	import { join } from "node:path";
18	import type { TranslationAdapter } from "./api-translation.ts";
19	
20	/**
21	 * A translatable unit. `markdown` is translated per file (whole-file, e.g. guides); `text` (short
22	 * labels) and `prose` (block-level API/cssdoc prose) units are batched together into one request.
23	 */
24	export interface TranslationUnit {
25	  kind: "markdown" | "text" | "prose";
26	  source: string;
27	  /** Only used to label markdown units in adapter prompts/logs. */
28	  filePath?: string;
29	}
30	
31	/** The cache directory (committed — it's the reusable translation memory, not a build artifact). */
32	const cacheDir = join(import.meta.dirname, "..", "i18n-cache");
33	
34	/** The stable content key for a unit: `sha256(kind \0 source)`, hex. */
35	export function keyFor(kind: string, source: string): string {
36	  return createHash("sha256").update(`${kind}�${source}`).digest("hex");
37	}
38	
39	interface CacheFile {
40	  version: 1;
41	  entries: Record<string, string>;
42	}
43	
44	/** A per-locale, per-namespace translation memory backed by a committed JSON file. */
45	export class TranslationMemory {
46	  private readonly path: string;
47	  private readonly entries: Map<string, string>;
48	  private readonly used = new Set<string>();
49	  hits = 0;
50	  misses = 0;
51	
52	  private constructor(path: string, entries: Map<string, string>) {
53	    this.path = path;
54	    this.entries = entries;
55	  }
56	
57	  /** Load (or start) the memory for `<locale>.<namespace>.json`. */
58	  static load(locale: string, namespace: string): TranslationMemory {
59	    const path = join(cacheDir, `${locale}.${namespace}.json`);
60	    if (!existsSync(path)) return new TranslationMemory(path, new Map());
61	    const parsed = JSON.parse(readFileSync(path, "utf8")) as CacheFile;
62	    return new TranslationMemory(path, new Map(Object.entries(parsed.entries ?? {})));
63	  }
64	
65	  /** A cached translation for this unit, or `undefined`. Marks the key as used. */
66	  get(kind: string, source: string): string | undefined {
67	    const key = keyFor(kind, source);
68	    const hit = this.entries.get(key);
69	    if (hit !== undefined) {
70	      this.used.add(key);
71	      this.hits += 1;
72	    }
73	    return hit;
74	  }
75	
76	  /** Store a translation and mark its key as used. */
77	  set(kind: string, source: string, translation: string): void {
78	    const key = keyFor(kind, source);
79	    this.entries.set(key, translation);
80	    this.used.add(key);
81	    this.misses += 1;
82	  }
83	
84	  /** Prune to the keys touched this run, then write stable (sorted) JSON. */
85	  save(): void {
86	    const pruned: Record<string, string> = {};
87	    for (const key of [...this.used].sort()) {
88	      const value = this.entries.get(key);
89	      if (value !== undefined) pruned[key] = value;
90	    }
91	    mkdirSync(cacheDir, { recursive: true });
92	    const payload: CacheFile = { version: 1, entries: pruned };
93	    writeFileSync(this.path, `${JSON.stringify(payload, null, 2)}\n`);
94	  }
95	}
96	
97	/**
98	 * Translate a set of units against the memory. Returns a map keyed by `keyFor(kind, source)` so
99	 * callers can look up each unit's translation (identical sources collapse to one entry).
100	 *
101	 * Diff: cache hits are served immediately. Objectify + translate: `text` misses are deduped and sent
102	 * to {@link TranslationAdapter.translateBatch} in one request; `markdown` misses are translated per
103	 * file. Destructure + save: results are written back into the memory keyed by content hash.
104	 */
105	export interface TranslateOptions {
106	  /**
107	   * Persist the memory after each markdown miss, so a long run (e.g. hundreds of API files) is
108	   * resumable: if a translation fails partway, the completed work is already saved and a re-run
109	   * serves it from cache. Off by default.
110	   */
111	  autosave?: boolean;
112	}
113	
114	export async function translateUnits(
115	  adapter: TranslationAdapter,
116	  memory: TranslationMemory,
117	  units: readonly TranslationUnit[],
118	  options: TranslateOptions = {},
119	): Promise<Map<string, string>> {
120	  const result = new Map<string, string>();
121	
122	  // Dedupe by content key so an identical string (e.g. a repeated sidebar label) translates once.
123	  const unique = new Map<string, TranslationUnit>();
124	  for (const unit of units) {
125	    const key = keyFor(unit.kind, unit.source);
126	    const cached = memory.get(unit.kind, unit.source);
127	    if (cached !== undefined) {
128	      result.set(key, cached);
129	      continue;
130	    }
131	    if (!unique.has(key)) unique.set(key, unit);
132	  }
133	
134	  const misses = [...unique.values()];
135	  const markdownMisses = misses.filter((u) => u.kind === "markdown");
136	  const textMisses = misses.filter((u) => u.kind === "text");
137	  const proseMisses = misses.filter((u) => u.kind === "prose");
138	
139	  // Markdown: per-file (keeps fidelity; batching large bodies risks the model dropping structure).
140	  // A single file's failure is logged and skipped rather than aborting the whole run.
141	  for (const [index, unit] of markdownMisses.entries()) {
142	    try {
143	      const translated = await adapter.translateMarkdown(unit.source, unit.filePath ?? "");
144	      memory.set("markdown", unit.source, translated);
145	      result.set(keyFor("markdown", unit.source), translated);
146	      if (options.autosave) memory.save();
147	      if ((index + 1) % 25 === 0) {
148	        console.log(`  … ${index + 1}/${markdownMisses.length} markdown files translated`);
149	      }
150	    } catch (error) {
151	      console.warn(
152	        `  ! skipped ${unit.filePath ?? "a markdown unit"}: ${error instanceof Error ? error.message : String(error)}`,
153	      );
154	    }
155	  }
156	
157	  // Poison-cache guard: an adapter that can't translate prose (the glossary) would only pass a prose
158	  // block through near-unchanged. Serve that passthrough into the rendered file, but DON'T cache it —
159	  // caching it under the prose key would permanently mask the block from a later claude run, since the
160	  // content hash wouldn't change. It must stay a miss.
161	  const batchable = [...textMisses];
162	  if (adapter.translatesProse === false) {
163	    for (const unit of proseMisses) result.set(keyFor("prose", unit.source), unit.source);
164	  } else {
165	    batchable.push(...proseMisses);
166	  }
167	
168	  // Text + prose: objectify into one batched request (fewer round-trips). Persist each chunk as it
169	  // lands — with `autosave`, a long cold run stays resumable (a kill keeps completed chunks) and logs
170	  // progress, instead of writing nothing until the whole batch returns.
171	  if (batchable.length > 0) {
172	    const items = batchable.map((u) => ({ id: keyFor(u.kind, u.source), text: u.source }));
173	    const byId = new Map(items.map((item, index) => [item.id, batchable[index]]));
174	    const consumed = new Set<string>();
175	    const persist = (partial: Record<string, string>): void => {
176	      let added = 0;
177	      for (const [id, value] of Object.entries(partial)) {
178	        const unit = byId.get(id);
179	        if (unit === undefined || consumed.has(id)) continue;
180	        consumed.add(id);
181	        memory.set(unit.kind, unit.source, value);
182	        result.set(id, value);
183	        added += 1;
184	      }
185	      if (added === 0) return; // e.g. the final sweep re-seeing an already-persisted chunk
186	      if (options.autosave) memory.save();
187	      if (items.length > 1) {
188	        console.log(`  … ${consumed.size}/${items.length} labels + prose blocks translated`);
189	      }
190	    };
191	
192	    const batched = adapter.translateBatch
193	      ? await adapter.translateBatch(items, persist)
194	      : Object.fromEntries(
195	          await Promise.all(
196	            items.map(async (i) => [i.id, await adapter.translateText(i.text)] as const),
197	          ),
198	        );
199	    // Cover adapters that didn't stream through the callback (the per-item fallback above).
200	    persist(batched);
201	    // Anything still missing — a chunk that errored out, or a key the model dropped — renders as its
202	    // source text this run but is NOT cached, so it stays a miss and is retried next run rather than
203	    // being frozen as English in the committed memory.
204	    for (const unit of batchable) {
205	      const key = keyFor(unit.kind, unit.source);
206	      if (consumed.has(key)) continue;
207	      consumed.add(key);
208	      result.set(key, unit.source);
209	    }
210	  }
211	
212	  return result;
213	}
