1	/**
2	 * Translate the hand-written guide pages into each non-root locale, mirroring `build-api-locales`
3	 * for prose. The root (`docs/guide/*.md`) is the source; each locale gets a `docs/<locale>/guide/`
4	 * copy run through the configured adapter.
5	 *
6	 * Run with `DOCS_TRANSLATION_ADAPTER=claude-code` for real translations (shells out to `claude`);
7	 * the default `glossary` adapter is a keyless, deterministic fallback. Fenced code blocks, inline
8	 * code, and package names are preserved by the adapter, so examples and identifiers stay intact.
9	 *
10	 * Each page is diffed against a committed translation memory (keyed by content hash), so only new or
11	 * edited guides reach the adapter — re-running after a one-page edit costs one translation, not
12	 * seven. This is a manual workflow — guide translations are committed, not regenerated on every
13	 * build — so run it after editing the English guides, then review the diff.
14	 */
15	import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
16	import { join } from "node:path";
17	import { LOCALES } from "../.vitepress/i18n.ts";
18	import { createTranslationAdapter } from "./api-translation.ts";
19	import { TranslationMemory, keyFor, translateUnits } from "./translation-memory.ts";
20	
21	const docsRoot = join(import.meta.dirname, "..");
22	const guideDir = join(docsRoot, "guide");
23	const adapter = createTranslationAdapter();
24	
25	const pages = readdirSync(guideDir)
26	  .filter((name) => name.endsWith(".md"))
27	  .toSorted();
28	
29	const targets = Object.keys(LOCALES).filter((key) => key !== "root");
30	
31	for (const locale of targets) {
32	  const outDir = join(docsRoot, locale, "guide");
33	  mkdirSync(outDir, { recursive: true });
34	
35	  const memory = TranslationMemory.load(locale, "guides");
36	  const sources = pages.map((page) => ({
37	    page,
38	    source: readFileSync(join(guideDir, page), "utf8"),
39	  }));
40	
41	  const translations = await translateUnits(
42	    adapter,
43	    memory,
44	    sources.map(({ page, source }) => ({ kind: "markdown", source, filePath: `guide/${page}` })),
45	  );
46	
47	  for (const { page, source } of sources) {
48	    const translated = translations.get(keyFor("markdown", source)) ?? source;
49	    writeFileSync(join(outDir, page), `${translated.trimEnd()}\n`);
50	    console.log(`  ${locale}/guide/${page}`);
51	  }
52	
53	  memory.save();
54	  console.log(
55	    `✓ localized ${pages.length} guide pages for '${locale}' via '${adapter.name}' ` +
56	      `(${memory.misses} translated, ${memory.hits} cached)`,
57	  );
58	}
